import * as THREE from 'three/webgpu';
import {
  Fn,
  uniform,
  uv,
  vec2,
  vec3,
  color,
  mix,
  fract,
  sin,
  dot,
} from 'three/tsl';
import gsap from 'gsap';
import { createMSDFText } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'kinetic-3d-headline';
  group.userData.handlers = {};

  const disposables = [];
  const timelines = [];

  // ---------------------------------------------------------------------
  // Text content (data-driven, falls back to spec copy if absent)
  // ---------------------------------------------------------------------
  const textContent = Array.isArray(config.textContent) ? config.textContent : [];
  const getText = (role, fallback) => {
    const entry = textContent.find((t) => t && t.role === role);
    return entry && entry.text ? entry.text : fallback;
  };

  const captionText = getText('caption', 'NOVA ATELIER / CALIBRE PROGRAM');
  const heroText = getText('hero', 'TIME, MACHINED.');
  const subheadText = getText('subhead', 'Every calibre begins as a solid billet.');

  const PAPER = 0xe8ecf2;
  const ACCENT = 0xff2a38;

  // ---------------------------------------------------------------------
  // Backdrop: 7 x 5.5 plane, engineered vertical gradient + mono grain
  // ---------------------------------------------------------------------
  const backdropGeo = new THREE.PlaneGeometry(7, 5.5, 1, 1);
  disposables.push(backdropGeo);

  const hash21 = Fn(([p]) => {
    const h = dot(p, vec2(127.1, 311.7));
    return fract(sin(h).mul(43758.5453123));
  });

  const backdropTop = uniform(color(0x13131a));
  const backdropBottom = uniform(color(0x0b0b10));
  const vUv = uv();
  const gradientFactor = vUv.y.clamp(0.0, 1.0);
  const baseGradient = mix(backdropBottom, backdropTop, gradientFactor);
  const grainUv = vUv.mul(vec2(1536.0, 1536.0));
  const grainValue = hash21(grainUv).sub(0.5).mul(0.015);
  const backdropColorNode = baseGradient.add(vec3(grainValue, grainValue, grainValue));

  const backdropMat = new THREE.MeshBasicNodeMaterial();
  backdropMat.colorNode = backdropColorNode;
  disposables.push(backdropMat);

  const backdropMesh = new THREE.Mesh(backdropGeo, backdropMat);
  backdropMesh.name = 'headline-backdrop';
  backdropMesh.position.set(0, 0, -1.5);
  group.add(backdropMesh);

  // ---------------------------------------------------------------------
  // Text builder helper (MSDF only, via ctx.fontAtlas)
  // ---------------------------------------------------------------------
  const buildText = (text, opts) =>
    createMSDFText({
      text,
      fontAtlas: ctx.fontAtlas,
      family: opts.family,
      weight: opts.weight,
      fontSize: opts.size,
      letterSpacing: opts.letterSpacing,
      lineHeight: opts.lineHeight,
      color: opts.colorHex,
      align: 'center',
    });

  const centerGroupX = (obj) => {
    obj.updateMatrixWorld(true);
    const box = new THREE.Box3().setFromObject(obj);
    const centerX = (box.max.x + box.min.x) / 2;
    obj.position.x = -centerX;
    return box.max.x - box.min.x;
  };

  // ---------------------------------------------------------------------
  // Caption kicker — y=1.15, JetBrains Mono 700 uppercase
  // ---------------------------------------------------------------------
  const captionGroup = buildText(captionText, {
    family: 'JetBrains Mono',
    weight: 700,
    size: 0.09,
    letterSpacing: 0.12,
    lineHeight: 1.4,
    colorHex: PAPER,
  });
  captionGroup.name = 'caption-text';
  centerGroupX(captionGroup);
  captionGroup.position.y = 1.15;
  group.add(captionGroup);

  // ---------------------------------------------------------------------
  // Hero headline — y=0.4, Lora 600, per-word z parallax offsets
  // ---------------------------------------------------------------------
  const heroGroup = new THREE.Group();
  heroGroup.name = 'hero-text';
  heroGroup.position.set(0, 0.4, 0);
  group.add(heroGroup);

  const heroWords = heroText.split(' ').filter(Boolean);
  const heroZOffsets = [0.12, 0.0, -0.12];
  const heroWordGroups = heroWords.map((word, i) => {
    const wordGroup = buildText(word, {
      family: 'Lora',
      weight: 600,
      size: 0.62,
      letterSpacing: -0.01,
      lineHeight: 1.05,
      colorHex: PAPER,
    });
    wordGroup.name = `hero-word-${i}`;
    wordGroup.position.z = heroZOffsets[i % heroZOffsets.length];
    heroGroup.add(wordGroup);
    return wordGroup;
  });

  const spaceWidth = 0.62 * 0.32;
  let cursorX = 0;
  const wordWidths = heroWordGroups.map((wg) => {
    wg.updateMatrixWorld(true);
    const box = new THREE.Box3().setFromObject(wg);
    return box.max.x - box.min.x;
  });
  const wordLayoutX = wordWidths.map((w) => {
    const x = cursorX;
    cursorX += w + spaceWidth;
    return x;
  });
  const totalHeroWidth = cursorX - spaceWidth;
  heroWordGroups.forEach((wg, i) => {
    wg.position.x = wordLayoutX[i] - totalHeroWidth / 2;
  });

  // ---------------------------------------------------------------------
  // Subhead — y=-0.65, JetBrains Mono 400
  // ---------------------------------------------------------------------
  const subheadGroup = buildText(subheadText, {
    family: 'JetBrains Mono',
    weight: 400,
    size: 0.2,
    letterSpacing: 0.02,
    lineHeight: 1.35,
    colorHex: PAPER,
  });
  subheadGroup.name = 'subhead-text';
  centerGroupX(subheadGroup);
  subheadGroup.position.y = -0.65;
  group.add(subheadGroup);

  // ---------------------------------------------------------------------
  // Accent underline rule — 2.6 x 0.045 plane, anchored left, emissive
  // ---------------------------------------------------------------------
  const underlineWidth = 2.6;
  const underlineHeight = 0.045;
  const underlineGeo = new THREE.PlaneGeometry(underlineWidth, underlineHeight, 1, 1);
  underlineGeo.translate(underlineWidth / 2, 0, 0); // local origin at left edge
  disposables.push(underlineGeo);

  const underlineMat = new THREE.MeshStandardNodeMaterial({
    color: ACCENT,
    emissive: ACCENT,
    emissiveIntensity: 1.2,
    roughness: 0.55,
    metalness: 0.35,
    clearcoat: 0.2,
  });
  disposables.push(underlineMat);

  const underlineMesh = new THREE.Mesh(underlineGeo, underlineMat);
  underlineMesh.name = 'accent-underline';
  underlineMesh.position.set(-underlineWidth / 2, -0.05, 0.01);
  underlineMesh.scale.x = 0.0001;
  group.add(underlineMesh);

  // ---------------------------------------------------------------------
  // Animation helpers (GSAP presets, applied directly — not primitives)
  // ---------------------------------------------------------------------
  const prepFade = (targetGroup) => {
    targetGroup.children.forEach((child) => {
      if (child.material) {
        child.material.transparent = true;
        child.material.opacity = 0;
      }
    });
  };

  const riseIn = (targetGroup, { delay = 0, duration = 0.7, riseDistance = 0.4, ease = 'power3.out' } = {}) => {
    const startY = targetGroup.position.y;
    prepFade(targetGroup);
    targetGroup.position.y = startY + riseDistance;
    const tl = gsap.timeline({ delay });
    tl.to(targetGroup.position, { y: startY, duration, ease }, 0);
    targetGroup.children.forEach((child) => {
      if (child.material) tl.to(child.material, { opacity: 1, duration, ease }, 0);
    });
    return tl;
  };

  const fadeUp = (targetGroup, { delay = 0, duration = 0.5, distance = 0.2, ease = 'power2.out' } = {}) => {
    const startY = targetGroup.position.y;
    prepFade(targetGroup);
    targetGroup.position.y = startY + distance;
    const tl = gsap.timeline({ delay });
    tl.to(targetGroup.position, { y: startY, duration, ease }, 0);
    targetGroup.children.forEach((child) => {
      if (child.material) tl.to(child.material, { opacity: 1, duration, ease }, 0);
    });
    return tl;
  };

  // Caption: rise-in immediately on load.
  timelines.push(riseIn(captionGroup, { delay: 0, duration: 0.7, riseDistance: 0.4, ease: 'power3.out' }));

  // ---------------------------------------------------------------------
  // Cinematic primitives — applied exclusively via ctx.primitives
  // ---------------------------------------------------------------------
  const primitiveConfigs = Array.isArray(config.cinematicPrimitives) ? config.cinematicPrimitives : [];
  let heroGlyphCount = heroWords.join('').length || 1;
  let kineticStaggerMs = 60;

  primitiveConfigs.forEach((primitive) => {
    const applyPrimitive = ctx.primitives && ctx.primitives[primitive.name];
    if (typeof applyPrimitive !== 'function') return;

    const params = primitive.params || {};
    if (primitive.name === 'kinetic-text' && typeof params.staggerMs === 'number') {
      kineticStaggerMs = params.staggerMs;
    }

    const handle = applyPrimitive(heroGroup, params);
    if (handle && typeof handle.kill === 'function') {
      timelines.push(handle);
    }
  });

  // Estimated moment the final glyph lands (700ms travel + left-to-right stagger).
  const glyphTravelSeconds = 0.7;
  const totalKineticDuration = ((heroGlyphCount - 1) * (kineticStaggerMs / 1000)) + glyphTravelSeconds;

  // Weighted-settle on the hero group, triggered by the final glyph landing.
  heroGroup.scale.setScalar(1.04);
  const settleTl = gsap.timeline({ delay: totalKineticDuration });
  settleTl.to(heroGroup.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0);
  timelines.push(settleTl);

  // Accent underline reveal — 120ms after the last glyph lands.
  const underlineDelay = totalKineticDuration + 0.12;
  const underlineTl = gsap.timeline({ delay: underlineDelay });
  underlineTl.set(underlineMesh.scale, { x: 0 });
  underlineTl.to(underlineMesh.scale, { x: 1, duration: 0.5, ease: 'power2.out' }, 0);
  timelines.push(underlineTl);

  // Subhead fade-up, synced with the underline reveal.
  timelines.push(fadeUp(subheadGroup, { delay: underlineDelay, duration: 0.5, distance: 0.2, ease: 'power2.out' }));

  // ---------------------------------------------------------------------
  // Cleanup
  // ---------------------------------------------------------------------
  group.userData.cleanup = () => {
    timelines.forEach((tl) => {
      if (tl && typeof tl.kill === 'function') tl.kill();
    });
    timelines.length = 0;

    group.traverse((obj) => {
      if (obj.geometry && typeof obj.geometry.dispose === 'function') {
        obj.geometry.dispose();
      }
      if (obj.material) {
        const materials = Array.isArray(obj.material) ? obj.material : [obj.material];
        materials.forEach((mat) => {
          if (mat && typeof mat.dispose === 'function') mat.dispose();
        });
      }
    });

    disposables.forEach((res) => {
      if (res && typeof res.dispose === 'function') res.dispose();
    });
    disposables.length = 0;
  };

  return group;
}
